/** @param {NS} ns */
export async function main(ns) {
  const player = ns.getPlayer();
  if (player.skills.hacking < 1) {
    ns.purchaseServer('hacknet-node-0', 1);
    await ns.sleep(100);
    ns.upgradeHomeRam(1);
    await ns.sleep(100);
  }
  while (true) {
    const target = 'n00dles';
    const canHack = ns.getHackingLevel() > ns.getServerRequiredHackingLevel(target);
    if (canHack) {
      await ns.hack(target);
    } else {
      await ns.grow(target);
    }
    await ns.sleep(50);
  }
}

